    @Test void strictFactSelectionAndFiniteUnsupportedNeverPublishModelNumbers()throws Exception {
        for(String inner:Arrays.asList("{\"status\":\"ANSWER\",\"factKeys\":[],\"reason\":null}","{\"status\":\"ANSWER\",\"factKeys\":[\"UNKNOWN\"],\"reason\":null}","{\"status\":\"ANSWER\",\"factKeys\":[\"TARGET_RATE\",\"TARGET_RATE\"],\"reason\":null}","{\"status\":\"ANSWER\",\"factKeys\":[\"TARGET_RATE\"],\"reason\":null,\"value\":99}","{\"status\":\"UNSUPPORTED\",\"factKeys\":[\"TARGET_RATE\"],\"reason\":\"MEDICAL_ADVICE\"}","{\"status\":\"UNSUPPORTED\",\"factKeys\":[],\"reason\":\"FREE_TEXT\"}")){peer.json(outer(inner));error(all(),502,"AI_INVALID_RESPONSE");networkExited();auditExited();}
        for(String reason:Arrays.asList("MEDICAL_ADVICE","SCOPE_CHANGE_REQUIRED","UNSUPPORTED_QUESTION")){peer.json(outer(json.writeValueAsString(object("status","UNSUPPORTED","factKeys",Collections.emptyList(),"reason",reason))));JsonNode d=success(all());assertEquals("UNSUPPORTED",d.path("status").asText());assertEquals(reason,d.path("reason").asText());assertEquals(0,d.path("facts").size());assertEquals(6,d.path("scope").path("n").asInt());assertEquals("UNSUPPORTED",audit(d.path("auditRef").asText()).get("outcome"));networkExited();auditExited();}
        AiGatewayLoopbackPeer.Exchange x=answer("TARGET_RATE","COHORT_SIZE","DATA_COMPLETENESS","CLINICAL_SUMMARY");java.util.Map<String,Object> f=filters();f.put("ids",Arrays.asList("1","3","6"));String q="合成问题原文：当前范围达标率？",request=body("COHORT",f,q);request=request.substring(0,request.length()-1)+",\"previousQuestions\":[\"第一轮合成问题\",\"第二轮合成问题\"]}";JsonNode d=success(request);assertEquals(4,d.path("facts").size());JsonNode wire=json.readTree(x.body);assertFalse(wire.path("stream").asBoolean());assertEquals("disabled",wire.path("thinking").path("type").asText());assertEquals("json_object",wire.path("response_format").path("type").asText());JsonNode user=json.readTree(wire.path("messages").get(1).path("content").asText());assertEquals(q,user.path("question").asText());assertEquals(2,user.path("previousQuestions").size());assertEquals(3,user.path("scope").path("n").asInt());assertEquals(3,user.path("scope").size());for(String forbidden:Arrays.asList("合成患者1","RA-P03-00001","110101198610070011","patientId","visitId","doctorId","filters","甲氨蝶呤"))assertFalse(user.toString().contains(forbidden),forbidden);networkExited();auditExited();assertEquals(10,count("ra_ai_chat_audit"));
    }
    @Test void postInsertFaultRollsBackNewEventKeepsOldAndNeverPublishesAnswer()throws Exception {
        answer("TARGET_RATE");JsonNode old=success(all());String ref=old.path("auditRef").asText();Map<String,String> event=audit(ref);String source=digest();long runs=count("ra_ai_analysis_run");
        final int[] cuts={0};auditObserved.afterInsert=()->{cuts[0]++;throw new IllegalStateException("synthetic post-insert pre-commit");};answer("TARGET_RATE");error(all(),503,"SERVICE_UNAVAILABLE");assertEquals(1,cuts[0]);assertEquals(1,auditObserved.ownerSawInserted,"实际SQL插入后的同事务行已到达");assertEquals(1,count("ra_ai_chat_audit"),"rollback后不得残留新event");assertEquals(event,audit(ref));assertEquals(source,digest());assertEquals(runs,count("ra_ai_analysis_run"));assertEquals(1,auditObserved.rollbacks);networkExited();auditExited();
        auditObserved.failInsert=true;answer("TARGET_RATE");error(all(),503,"SERVICE_UNAVAILABLE");assertEquals(1,count("ra_ai_chat_audit"));assertEquals(event,audit(ref));auditExited();auditObserved.failInsert=false;
        answer("TARGET_RATE");JsonNode next=success(all());assertNotEquals(ref,next.path("auditRef").asText());assertEquals(2,count("ra_ai_chat_audit"));assertEquals(event,audit(ref));networkExited();auditExited();
        try(java.io.InputStream ddl=getClass().getResourceAsStream("/sql/20261012_ai_chat_audit.sql")){sql(new Scanner(ddl,"UTF-8").useDelimiter("\\A").next().trim());}context.close();buildContext(false);assertEquals(event,audit(ref));answer("TARGET_RATE");success(all());assertEquals(3,count("ra_ai_chat_audit"));networkExited();auditExited();
    }
    @Test void permanentHeaderAndBodyStallsExitActualPeerAndRecoverCapacity()throws Exception {
        for(boolean bodyStall:new boolean[]{false,true}){byte[] response=bodyStall?AiGatewayLoopbackPeer.http(200,"Content-Type: application/json\r\nContent-Length: 1000\r\n",new byte[]{'{'}):new byte[0];AiGatewayLoopbackPeer.Exchange x=peer.reply(response);Caller caller=new Caller(all(),false);
            try{assertTrue(x.received.await(2,TimeUnit.SECONDS));assertEquals(0,observed.active.get());assertTrue(caller.done.await(5500,TimeUnit.MILLISECONDS));long elapsed=TimeUnit.NANOSECONDS.toMillis(caller.finished-caller.started);assertTrue(elapsed>=3500&&elapsed<=5500);assertEquals(504,caller.response.getResponse().getStatus());assertTrue(caller.data().isNull());assertTrue(x.eof.await(1,TimeUnit.SECONDS),"真实peer自行EOF先于finally");networkExited();auditExited();assertEquals("AI_TIMEOUT",audit(auditObserved.insertedRef).get("outcome"));answer("TARGET_RATE");success(all());networkExited();auditExited();}finally{caller.fallbackCleanup();}}
        assertEquals(4,peer.requests.get());assertEquals(4,count("ra_ai_chat_audit"));assertNull(peer.failure.get());
    }
    @Test void actualCallerInterruptIsImmediatePreservedAndNeverAudited()throws Exception {
        AiGatewayLoopbackPeer.Exchange x=peer.reply(new byte[0]);Caller caller=new Caller(all(),false);try{assertTrue(x.received.await(2,TimeUnit.SECONDS));caller.thread.interrupt();assertTrue(x.eof.await(1000,TimeUnit.MILLISECONDS),"caller主动取消真实socket，不能靠4.5s计时器");assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-caller.started)<3000);assertTrue(caller.done.await(500,TimeUnit.MILLISECONDS));assertNull(caller.error);assertTrue(caller.interrupted);assertEquals(503,caller.response.getResponse().getStatus());assertTrue(caller.data().isNull());assertEquals(0,count("ra_ai_chat_audit"));networkExited();auditExited();}finally{caller.fallbackCleanup();}
        Caller pre=new Caller(all(),true);try{assertTrue(pre.done.await(2,TimeUnit.SECONDS));assertTrue(pre.interrupted);assertEquals(503,pre.response.getResponse().getStatus());assertEquals(1,peer.requests.get());assertEquals(0,count("ra_ai_chat_audit"));networkExited();auditExited();}finally{pre.fallbackCleanup();}answer("TARGET_RATE");success(all());networkExited();auditExited();
    }
    @Test void twoOwnersRejectThirdWithoutQueueAndCloseRetiresActualCalls()throws Exception {
        AiGatewayLoopbackPeer.Exchange x=peer.reply(new byte[0]);Caller a=new Caller(all(),false);Caller b=null;try{assertTrue(x.received.await(2,TimeUnit.SECONDS));AiGatewayLoopbackPeer.Exchange y=peer.reply(new byte[0]);b=new Caller(all(),false);assertTrue(y.received.await(2,TimeUnit.SECONDS));com.wenwen.ai.chat.ChatGateway gateway=context.getBean(com.wenwen.ai.chat.ChatGateway.class);java.lang.reflect.Field field=gateway.getClass().getDeclaredField("executor");field.setAccessible(true);ThreadPoolExecutor e=(ThreadPoolExecutor)field.get(gateway);assertEquals(2,e.getActiveCount());assertEquals(2,e.getMaximumPoolSize());assertTrue(e.getQueue() instanceof SynchronousQueue);error(all(),429,"AI_BUSY");assertEquals(2,peer.requests.get());assertEquals(2,e.getActiveCount());assertEquals(1,count("ra_ai_chat_audit"));
            gateway.close();assertTrue(x.eof.await(1,TimeUnit.SECONDS));assertTrue(y.eof.await(1,TimeUnit.SECONDS));assertTrue(a.done.await(1,TimeUnit.SECONDS));assertTrue(b.done.await(1,TimeUnit.SECONDS));assertEquals(503,a.response.getResponse().getStatus());assertEquals(503,b.response.getResponse().getStatus());assertTrue(a.data().isNull());assertTrue(b.data().isNull());assertTrue(e.isTerminated());networkExited();auditExited();error(all(),429,"AI_BUSY");assertEquals(2,peer.requests.get());networkExited();auditExited();
        }finally{a.fallbackCleanup();if(b!=null)b.fallbackCleanup();}
    }
    @Test void latePeerCannotPublishOrRetireNextOwnerAfterTimeout()throws Exception {
        AiGatewayLoopbackPeer.Exchange late=peer.holdJson(outer("{\"status\":\"ANSWER\",\"factKeys\":[\"TARGET_RATE\"],\"reason\":null}"));Caller old=new Caller(all(),false);try{assertTrue(late.received.await(2,TimeUnit.SECONDS));assertTrue(old.done.await(5500,TimeUnit.MILLISECONDS));assertEquals(504,old.response.getResponse().getStatus());assertTrue(late.eof.await(1,TimeUnit.SECONDS));networkExited();auditExited();String ref=auditObserved.insertedRef;Map<String,String> event=audit(ref);
            AiGatewayLoopbackPeer.Exchange fresh=peer.holdJson(outer("{\"status\":\"ANSWER\",\"factKeys\":[\"TARGET_RATE\"],\"reason\":null}"));Caller next=new Caller(all(),false);try{assertTrue(fresh.received.await(2,TimeUnit.SECONDS));late.allow.countDown();assertTrue(late.attempted.await(1,TimeUnit.SECONDS));assertEquals(1,count("ra_ai_chat_audit"));assertEquals(event,audit(ref));assertEquals(1,next.done.getCount());fresh.allow.countDown();JsonNode d=next.data();assertEquals("ANSWER",d.path("status").asText());assertNotEquals(ref,d.path("auditRef").asText());assertEquals(2,count("ra_ai_chat_audit"));networkExited();auditExited();}finally{fresh.allow.countDown();next.fallbackCleanup();}
        }finally{late.allow.countDown();old.fallbackCleanup();}
    }
    @Test void strictOuterTransportBoundsAndHttpErrorsStayOneShot()throws Exception {
        java.lang.reflect.Field system=com.wenwen.ai.chat.ChatProtocol.class.getDeclaredField("SYSTEM");system.setAccessible(true);byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(((String)system.get(null)).getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder();for(byte b:hash)hex.append(String.format(java.util.Locale.ROOT,"%02x",b&255));assertEquals("e48fc073c7e89d71e565795cb3b41285ec21f2c03bba9a6023620604758733e9",hex.toString());assertEquals("dev-chat-facts-v02",com.wenwen.ai.chat.ChatProtocol.PROMPT_VERSION);
        String inner="{\"status\":\"ANSWER\",\"factKeys\":[\"TARGET_RATE\"],\"reason\":null}",valid=outer(inner);for(String bad:Arrays.asList(valid+" {}",valid.replace("\"object\":\"chat.completion\"","\"object\":\"chat.completion\",\"object\":\"chat.completion\""),outer(inner.replace("\"reason\":null","\"reason\":null,\"reason\":null")),valid.replace("\"finish_reason\":\"stop\"","\"finish_reason\":\"length\""),valid.replace("\"role\":\"assistant\"","\"role\":\"assistant\",\"tool_calls\":[]"),valid.replace("\"prompt_tokens\":1","\"prompt_tokens\":-1"),"\ufeff"+valid)){
            AiGatewayLoopbackPeer.Exchange x=peer.json(bad);error(all(),502,"AI_INVALID_RESPONSE");assertTrue(x.eof.await(1,TimeUnit.SECONDS));networkExited();auditExited();}
        byte[] bytes=valid.getBytes(java.nio.charset.StandardCharsets.UTF_8);for(int size:new int[]{16384,16385}){byte[] b=Arrays.copyOf(bytes,size);Arrays.fill(b,bytes.length,b.length,(byte)' ');AiGatewayLoopbackPeer.Exchange x=peer.reply(AiGatewayLoopbackPeer.http(200,"Content-Type: application/json\r\nContent-Length: "+size+"\r\n",b));if(size==16384)success(all());else error(all(),502,"AI_INVALID_RESPONSE");assertTrue(x.eof.await(1,TimeUnit.SECONDS));networkExited();auditExited();}
        String cached=valid.replace("\"total_tokens\":2","\"total_tokens\":2,\"prompt_cache_hit_tokens\":0,\"prompt_cache_miss_tokens\":1");peer.json(cached);success(all());
        for(int status:new int[]{401,408,503,302}){int before=peer.requests.get();String headers="Content-Length: 0\r\n"+(status==302?"Location: "+peer.endpoint()+"\r\n":status==401?"WWW-Authenticate: Basic realm=synthetic\r\n":"Retry-After: 0\r\n");AiGatewayLoopbackPeer.Exchange x=peer.reply(AiGatewayLoopbackPeer.http(status,headers,new byte[0])),forbidden=answer("TARGET_RATE");error(all(),502,"AI_HTTP_ERROR");assertEquals(before+1,peer.requests.get());assertEquals(1,forbidden.received.getCount());peer.discardUnused(forbidden);assertTrue(x.eof.await(1,TimeUnit.SECONDS));networkExited();auditExited();}
        assertEquals(peer.requests.get(),count("ra_ai_chat_audit"));assertNull(peer.failure.get());
    }
